acpi_status acpi_ut_verify_cdat_checksum ( struct acpi_table_cdat * cdat_table , u32 length ) { u8 checksum ; if ( checksum != cdat_table -> checksum ) { ACPI_BIOS_WARNING ( ( AE_INFO , "Incorrect checksum in table [%4.4s] - 0x%2.2X, " "should be 0x%2.2X" , acpi_gbl_CDAT , cdat_table -> checksum , checksum ) ) ; return ( AE_BAD_CHECKSUM ) ; } cdat_table -> checksum = checksum ; return ( AE_OK ) ; } 